public class Solution {
    enum State { IDLE, COIN_INSERTED, DISPENSING }
    enum Action { INSERT_COIN, SELECT_ITEM, DISPENSE_COMPLETE }

    public static State transition(State current, Action action) {
        return switch (current) {
            case IDLE -> {
                if (action == Action.INSERT_COIN) yield State.COIN_INSERTED;
                System.out.println("Invalid action for IDLE state");
                yield current;
            }
            case COIN_INSERTED -> {
                if (action == Action.SELECT_ITEM) yield State.DISPENSING;
                System.out.println("Invalid action for COIN_INSERTED state");
                yield current;
            }
            case DISPENSING -> {
                if (action == Action.DISPENSE_COMPLETE) yield State.IDLE;
                System.out.println("Dispense in progress");
                yield current;
            }
        };
    }

    public static void main(String[] args) {
        State state = State.IDLE;
        System.out.println("Initial State: " + state);
        state = transition(state, Action.INSERT_COIN);
        System.out.println("After Coin: " + state);
        state = transition(state, Action.SELECT_ITEM);
        System.out.println("After Selection: " + state);
    }
}

public class Solution {
    public static int charValue(char ch) {
        return switch (ch) {
            case 'I' -> 1;
            case 'V' -> 5;
            case 'X' -> 10;
            case 'L' -> 50;
            case 'C' -> 100;
            case 'D' -> 500;
            case 'M' -> 1000;
            default  -> 0;
        };
    }

    public static int romanToInt(String s) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int current = charValue(s.charAt(i));
            if (i + 1 < s.length() && current < charValue(s.charAt(i + 1))) {
                total -= current;
            } else {
                total += current;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        String roman = "MCMXCIV"; // 1994
        System.out.println("Roman Numeral: " + roman);
        System.out.println("Parsed Integer: " + romanToInt(roman));
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public static void executeInstructions(String[] instructions) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String line : instructions) {
            String[] parts = line.split(" ");
            String op = parts[0].toUpperCase();
            switch (op) {
                case "PUSH" -> stack.push(Integer.parseInt(parts[1]));
                case "ADD" -> {
                    int b = stack.pop();
                    int a = stack.pop();
                    stack.push(a + b);
                }
                case "PRINT" -> System.out.println("Top of Stack: " + stack.peek());
                case "POP" -> stack.pop();
                default -> System.out.println("Unknown Opcode: " + op);
            }
        }
    }

    public static void main(String[] args) {
        String[] program = {"PUSH 15", "PUSH 35", "ADD", "PRINT"};
        executeInstructions(program);
    }
}

